command:
// Remet les jeux de cartes du monde au niveau des compendiums de patrons, par
// deux gestes de nature différente :
//
//  - les bibliothèques du monde sont TOUTES détruites, puis reconstruites pour
//    chaque personnage par le moteur lui-même (`updateDeckForUser`, le chemin de
//    la montée de niveau) : une bibliothèque n'a pas de composition propre, elle
//    expose les cartes débloquées par les niveaux de classe du personnage. C'est
//    le seul geste qui y fasse entrer les cartes AJOUTÉES aux compendiums et qui
//    en retire celles qui en ont disparu ;
//  - le deck de combat, lui, appartient au joueur : sa composition et ses
//    exemplaires sont son travail, et rien ne les touche. Chacune de ses cartes
//    est seulement réalignée sur la carte de MÊME NOM du compendium — coûts,
//    portées, dégâts, effets, visuel, description. Les cartes du monde sont des
//    copies sans lien vers leur source : le nom est leur seule identité commune,
//    et il est unique d'un bout à l'autre des patrons.
//
// À lancer hors combat : une carte remise au niveau de son patron y perd son
// état de round (charges déjà dépensées, carte déjà jouée).
(async () => {
    const PATTERN_PACK = "decks-pattern-fq8";
    const DECK_TYPE = "DECK";
    const SPELLBOOK_TYPE = "SPELLBOOK";
    // Les patrons dont les cartes ne se construisent pas : d'autres cartes les
    // mettent en jeu. Deux d'entre elles portent le nom d'une carte de deck de
    // base avec d'autres valeurs (niveau, exemplaires) — les decks de base
    // gagnent donc toujours l'homonymie.
    const GENERATED_SUFFIXES = [" Generated", " Runes"];
    // Ce qu'une carte de deck tient de son patron. Hors de cette liste : son nom
    // (l'identité, inchangée par définition) et `face`, `drawn`, `origin`,
    // `sort`, `flags`, qui disent où elle en est dans son jeu, pas ce qu'elle
    // fait.
    const SYNCED_FIELDS = ["description", "suit", "value", "back", "faces", "width", "height", "system"];

    const t = (key, data) => data
        ? game.i18n.format("FQCARDENGINE." + key, data)
        : game.i18n.localize("FQCARDENGINE." + key);

    if (!game.user.isGM) return ui.notifications.warn(t("PatternSyncGMOnly"));

    // Tous les modules qui livrent un compendium de patrons, le moteur en tête :
    // un module de contenu peut en apporter d'autres classes. Même règle que
    // `PackUtils` côté moteur, qu'une macro ne peut pas lire.
    const ownCollection = FqCardEngineModule.moduleName + "." + PATTERN_PACK;
    const packs = [
        game.packs.get(ownCollection),
        ...game.packs.filter(pack => pack.metadata?.name === PATTERN_PACK && pack.collection !== ownCollection)
    ].filter(Boolean);

    const patternDecks = [];
    for (const pack of packs) patternDecks.push(...await pack.getDocuments());
    const isGenerated = deck => GENERATED_SUFFIXES.some(suffix => String(deck.name).endsWith(suffix));

    // Index des patrons par nom de carte : les decks de base d'abord, les decks
    // de cartes générées ensuite, et dans chaque passe le premier compendium
    // rencontré gagne — le moteur avant les modules de contenu.
    const patterns = new Map();
    const indexDecks = decks => {
        for (const deck of decks) {
            for (const card of deck.cards) {
                if (!patterns.has(card.name)) patterns.set(card.name, card);
            }
        }
    };
    indexDecks(patternDecks.filter(deck => !isGenerated(deck)));
    indexDecks(patternDecks.filter(isGenerated));
    if (!patterns.size) return ui.notifications.error(t("PatternSyncNoPack"));

    const spellbooks = game.cards.filter(stack => stack.system?.fq?.type === SPELLBOOK_TYPE);
    // Les personnages dont le moteur sait refaire la bibliothèque : il lui faut
    // une classe FQ principale, et un utilisateur à qui attribuer le jeu.
    const owners = game.users.filter(
        user => user.character && FqCardEngineModule.cst.userFQClasses(user).length);
    const decks = () => game.cards.filter(stack => stack.system?.fq?.type === DECK_TYPE);
    if (!decks().length && !spellbooks.length && !owners.length) {
        return ui.notifications.warn(t("PatternSyncNothingToDo"));
    }

    const confirmed = await foundry.applications.api.DialogV2.confirm({
        window: {title: t("PatternSyncTitle")},
        content: "<p>" + t("PatternSyncConfirmDecks", {decks: decks().length, patterns: patterns.size}) + "</p>"
            + "<p class=\"notes\">"
            + t("PatternSyncConfirmSpellbooks", {deleted: spellbooks.length, rebuilt: owners.length})
            + "</p>",
        modal: true,
        rejectClose: false
    });
    if (!confirmed) return;

    // Toutes les bibliothèques partent d'abord, celles qu'aucun personnage ne
    // réclame plus comprises (joueur dépossédé, doublon laissé par une
    // reconstruction interrompue) : la reconstruction du moteur n'en retrouve
    // qu'une par utilisateur. Elle repart donc d'un instantané de niveaux vide,
    // ce qui neutralise au passage son retrait de cartes du deck de combat —
    // c'est bien ce qu'on veut ici : le deck appartient au joueur.
    if (spellbooks.length) await Cards.deleteDocuments(spellbooks.map(stack => stack.id));

    const rebuilt = [];
    for (const user of owners) {
        await FqCardEngineModule.updateDeckForUser(user.id);
        rebuilt.push(user.character.name);
    }

    // Réalignement des decks de combat, deck par deck. Une carte n'est réécrite
    // que si l'un de ses champs diffère de son patron, et seuls ces champs
    // partent : la comparaison passe par la sérialisation, le schéma ordonnant
    // les clés des deux côtés — `foundry.utils.diffObject` tiendrait tout
    // tableau pour modifié.
    const changedDecks = [];
    const orphans = new Set();
    let changedCards = 0;
    for (const deck of decks()) {
        const updates = [];
        for (const card of deck.cards) {
            const pattern = patterns.get(card.name);
            if (!pattern) {
                orphans.add(card.name);
                continue;
            }
            const source = pattern.toObject();
            const current = card.toObject();
            const changed = SYNCED_FIELDS.filter(
                field => JSON.stringify(current[field] ?? null) !== JSON.stringify(source[field] ?? null));
            if (!changed.length) continue;
            const update = {_id: card.id};
            for (const field of changed) update[field] = source[field];
            updates.push(update);
        }
        if (!updates.length) continue;
        await deck.updateEmbeddedDocuments("Card", updates);
        changedCards += updates.length;
        changedDecks.push(t("PatternSyncReportDeck", {deck: deck.name, cards: updates.length}));
    }

    ui.notifications.info(t("PatternSyncDone", {
        cards: changedCards, decks: changedDecks.length, spellbooks: rebuilt.length
    }));

    // Le détail part en message privé au MJ : les decks touchés, les
    // bibliothèques reconstruites, celles détruites sans retour, et les cartes
    // dont aucun patron ne porte plus le nom — renommées dans les compendiums,
    // ou retirées.
    const lines = [...changedDecks];
    if (rebuilt.length) lines.push(t("PatternSyncReportRebuilt", {characters: rebuilt.join(", ")}));
    if (spellbooks.length > rebuilt.length) {
        lines.push(t("PatternSyncReportDropped", {spellbooks: spellbooks.length - rebuilt.length}));
    }
    if (orphans.size) lines.push(t("PatternSyncReportOrphans", {names: [...orphans].sort().join(", ")}));
    lines.push(t("PatternSyncReportReopen"));
    await ChatMessage.create({
        content: "<h4>" + t("PatternSyncReportTitle") + "</h4><ul><li>" + lines.join("</li><li>") + "</li></ul>",
        whisper: ChatMessage.getWhisperRecipients("GM")
    });
})();
